void skip(const char* name){std::cout<<"[SKIP] "<<name<<"\n";++skips;}
void write(const mc::fs::path& p,const std::string& s){mc::fs::create_directories(p.parent_path());std::ofstream f(p,std::ios::binary);f<<s;}
#ifdef _WIN32
DWORD run_crash_restore_child(const mc::fs::path& folder,const mc::fs::path& database,const mc::fs::path& state,const std::string& version){
    std::wstring executable(32768,L'\0');const auto length=GetModuleFileNameW(nullptr,executable.data(),static_cast<DWORD>(executable.size()));if(length==0||length>=executable.size())return static_cast<DWORD>(-1);executable.resize(length);
    std::wstring command=L"\""+executable+L"\" --crash-restore \""+folder.wstring()+L"\" \""+database.wstring()+L"\" \""+state.wstring()+L"\" "+mc::fs::u8path(version).wstring();
    STARTUPINFOW startup{};startup.cb=sizeof(startup);PROCESS_INFORMATION process{};
    if(!CreateProcessW(executable.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&startup,&process))return static_cast<DWORD>(-1);
    WaitForSingleObject(process.hProcess,INFINITE);DWORD code=static_cast<DWORD>(-1);GetExitCodeProcess(process.hProcess,&code);CloseHandle(process.hThread);CloseHandle(process.hProcess);return code;
}
#endif
